+static void counting_sort_pass(uint32_t* a, uint32_t* output, size_t n, int shift) {
+    int counts[256] = {0};
+    // Counting pass
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t digit = (a[i] >> shift) & 0xFF;
+        counts[digit]++;
+    }
