+    // Prefix sum pass
+    int sum = 0;
+    for (int i = 0; i < 256; ++i) {
+        int temp = counts[i];
+        counts[i] = sum;
+        sum += temp;
+    }
+
+    // Distribution pass
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t digit = (a[i] >> shift) & 0xFF;
+        output[counts[digit]++] = a[i];
+    }
